import { parsePlanFile, PLAN_FILE_SUFFIX } from '../domain/planFile';
import type { PlansIndex } from './plansIndexFormat';
import { PlanStorageError, type PlanListing, type PlanRepository, type StoredPlan } from './PlanRepository';

/**
 * Read-only plans from a folder served with the app (`public/plans/`, US5): `index.json` (generated by
 * `tooling/plansIndex.ts`), `<id>.plan.json` and the GPX files. Plans are saved by downloading the plan file and
 * committing it to that folder.
 */
export class StaticFilePlanRepository implements PlanRepository {
  readonly capabilities = { save: false };

  /** @param baseUrl URL of the plans folder, ending with "/" */
  constructor(
    private readonly baseUrl: string,
    private readonly fetchFn: typeof fetch = (...args) => fetch(...args),
  ) {}

  private async text(file: string): Promise<string> {
    let response: Response;
    try {
      // revalidate: plan files change when the folder is edited (dev server) or redeployed
      response = await this.fetchFn(`${this.baseUrl}${encodeURIComponent(file)}`, { cache: 'no-cache' });
    } catch (error) {
      throw new PlanStorageError('unavailable', `The plans folder could not be read: ${(error as Error).message}`);
    }
    // a single-page-app fallback answers unknown files with the app's index.html instead of a 404
    const html = (response.headers.get('Content-Type') ?? '').includes('text/html');
    if (response.status === 404 || (response.ok && html)) {
      throw new PlanStorageError('notFound', `${file} was not found in the plans folder.`);
    }
    if (!response.ok) throw new PlanStorageError('unavailable', `${file} could not be read (HTTP ${response.status}).`);
    return response.text();
  }

  async list(): Promise<PlanListing> {
    let index: PlansIndex;
    try {
      index = JSON.parse(await this.text('index.json')) as PlansIndex;
    } catch (error) {
      if (error instanceof PlanStorageError && error.code === 'notFound') return { plans: [], tracks: [] };
      if (error instanceof PlanStorageError) throw error;
      throw new PlanStorageError('unavailable', 'The list of plans is damaged.');
    }
    return { plans: index.plans ?? [], tracks: index.tracks ?? [] };
  }

  async load(id: string): Promise<StoredPlan> {
    const plan = parsePlanFile(await this.text(`${id}${PLAN_FILE_SUFFIX}`));
    return { plan, gpx: await this.loadTrack(plan.track) };
  }

  loadTrack(file: string): Promise<string> {
    return this.text(file);
  }

  async save(): Promise<void> {
    throw new PlanStorageError('readOnly', 'Plans in the repository folder are saved by downloading the plan file.');
  }
}
